import React, { FC, useEffect, useState } from "react";

interface Transaction {
  id: number;
  amount: number;
  description: string;
  category?: string;
}

export function TransactionList(): JSX.Element {
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  useEffect(() => {
    fetch("/api/categorisation-api/transactions")
      .then(response => response.json())
      .then(data => setTransactions(data));
  }, []);

  const handleCategoryChange = async (id: number, category: string) => {
    await fetch(`/api/categorisation-api/transactions/${id}`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ category }),
    });
    setTransactions(prevTransactions => prevTransactions.map(transaction => (
      transaction.id === id ? { ...transaction, category } : transaction
    )));
  };

  return (
    <div>
      <h1>Transaction List</h1>
      <ul>
        {transactions.map(transaction => (
          <li key={transaction.id}>
            {transaction.description}: ${transaction.amount.toFixed(2)}
            {transaction.category ? (<span> - Category: {transaction.category}</span>) : null}
            <input
              type="text"
              placeholder="Enter category"
              onChange={(e) => handleCategoryChange(transaction.id, e.target.value)}
            />
          </li>
        ))}
      </ul>
    </div>
  );
}

import React, { FC, useEffect, useState } from "react";

interface Category {
  id: number;
  name: string;
  budget: number;
  spent: number;
}

export function BudgetOverview(): JSX.Element {
  const [categories, setCategories] = useState<Category[]>([]);

  useEffect(() => {
    fetch("/api/categorisation-api/transactions")
      .then(response => response.json())
      .then(data => {
        const categoriesData = data.reduce((acc: Record<string, Category>, transaction: { categoryId: number; amount: number }) => {
          const category = acc[transaction.categoryId.toString()];
          if (category) {
            acc[transaction.categoryId.toString()] = {
              ...category,
              spent: category.spent + transaction.amount,
            };
          } else {
            acc[transaction.categoryId.toString()] = {
              id: transaction.categoryId,
              name: "Unknown",
              budget: 0,
              spent: transaction.amount,
            };
          }
          return acc;
        }, {});
        setCategories(Object.values(categoriesData));
      });
  }, []);

  return (
    <div>
      <h1>Budget Overview</h1>
      <ul>
        {categories.map(category => (
          <li key={category.id}>{category.name}: Budget ${category.budget.toFixed(2)}, Spent ${category.spent.toFixed(2)}</li>
        ))}
      </ul>
    </div>
  );
}

