import React, { FC, useState } from "react";

interface FormData {
  description: string;
  photos: File[];
}

export function ClaimFilingForm(): JSX.Element {
  const [formData, setFormData] = useState<FormData>({ description: "", photos: [] });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>): void => {
    if (e.target.name === "description") {
      setFormData({ ...formData, description: e.target.value });
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>): void => {
    if (e.target.files) {
      setFormData({ ...formData, photos: Array.from(e.target.files) });
    }
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>): Promise<void> => {
    e.preventDefault();
    try {
      const formDataObj = new FormData();
      formDataObj.append("description", formData.description);
      formData.photos.forEach((photo, index) => {
        formDataObj.append(`photos[${index}]`, photo);
      });

      const response = await fetch("/api/claims-api/claims", {
        method: "POST",
        body: formDataObj,
      });

      if (!response.ok) {
        throw new Error("Failed to submit claim");
      }

      alert("Claim submitted successfully!");
    } catch (error) {
      console.error(error);
      alert("An error occurred while submitting the claim.");
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="description">Description:</label>
        <textarea
          id="description"
          name="description"
          value={formData.description}
          onChange={handleChange}
          required
        />
      </div>
      <div>
        <label htmlFor="photos">Photos:</label>
        <input
          id="photos"
          name="photos"
          type="file"
          multiple
          onChange={handleFileChange}
          required
        />
      </div>
      <button type="submit">Submit Claim</button>
    </form>
  );
}

